// Generated by `tsir make:listener`. Verifies the listener is bound to the
// `user.registered` event and that its handler runs without throwing.
import { describe, expect, test } from 'bun:test';

import { SendWelcomeEmailListener } from './send-welcome-email.listener.ts';
import { UserRegisteredEvent } from '../events/user-registered.event.ts';

describe('SendWelcomeEmailListener', () => {
  test('is bound to the user.registered event', () => {
    expect(SendWelcomeEmailListener.event).toBe(UserRegisteredEvent);
    expect(SendWelcomeEmailListener.name).toBe('send-welcome-email');
  });

  test('handler runs without throwing', () => {
    const context = {
      event: UserRegisteredEvent,
      listener: 'send-welcome-email',
      id: 'delivery-1',
      payload: { id: 'u_1' },
      occurredAt: Date.now(),
      attempt: 1,
      signal: new AbortController().signal,
      log: () => undefined,
    };
    expect(() => SendWelcomeEmailListener.handle(context as never)).not.toThrow();
  });
});
